ALTER TABLE "installation" ADD COLUMN "handover_customer_name" text;--> statement-breakpoint
ALTER TABLE "installation" ADD COLUMN "handover_customer_signature_key" text;--> statement-breakpoint
ALTER TABLE "installation" ADD COLUMN "handover_customer_signed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "installation" ADD CONSTRAINT "installation_countersign_ck" CHECK (("installation"."handover_customer_name" is null and "installation"."handover_customer_signature_key" is null and "installation"."handover_customer_signed_at" is null) or ("installation"."status" = 'completed' and "installation"."handover_at" is not null and pg_catalog.length(pg_catalog.btrim("installation"."handover_customer_name")) between 1 and 160 and "installation"."handover_customer_name" = pg_catalog.btrim("installation"."handover_customer_name") and "installation"."handover_customer_signature_key" ~ '^immutable/[0-9a-f-]{36}/installation-signatures/[0-9a-f-]{36}_[0-9a-f]{8}\.png$' and pg_catalog.isfinite("installation"."handover_customer_signed_at")));